<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\LoadService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('LOAD_UPDATE_DRAFT_OWN');$id=(int)($_GET['id']??0);$load=LoadService::find($id);if(!$load){http_response_code(404);exit('Load not found.');}if($load['current_status']!=='draft'){http_response_code(409);exit('Only a draft may be edited.');}$errors=[];$values=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$load;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{LoadService::update($id,$_POST,(int)Auth::user()['id'],(int)$_POST['row_version']);header('Location: '.Url::to('loads/view.php?id='.$id.'&updated=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}catch(Throwable$e){$errors[]='The draft could not be updated.';}}$pageTitle='Edit Load';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Edit <?=h($load['load_ref'])?></h1><p>Only draft records can be changed.</p></div></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="row_version" value="<?=h($load['row_version'])?>"><?php require BASE_PATH.'/app/Views/loads/form.php';?><div class="actions"><button class="button">Save changes</button><a class="button secondary" href="<?=h(Url::to('loads/view.php?id='.$id))?>">Cancel</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
